static int main_guard_check(u64 bias){for(u32 i=0;i<sizeof(main_guards)/sizeof(main_guards[0]);i++)if(*(const u64*)(bias+main_guards[i].offset)!=main_guards[i].word)return 0;return *(const u64*)(bias+0x4e800e8)==bias+0x2f6c7e4;}

static u64 main_packed_word(const u8 *p){u64 n=0;for(u32 i=0;i<8;i++)n|=(u64)p[i]<<(8*i);return n;}
static int main_unpack(u64 *dest){
 u32 cursor=0,index=0,total=MAIN_IMAGE_BYTES/8;
 while(cursor<sizeof(main_packed)){
  u32 tag=main_packed[cursor++],n=(tag&127)+((tag&128)?3:1);
  if(n>total-index)return 1;
  if(tag&128){
   if(sizeof(main_packed)-cursor<2)return 1;
   u32 distance=main_packed[cursor]|(main_packed[cursor+1]<<8);cursor+=2;
   if(!distance||distance>16383||distance>index)return 1;
   for(u32 i=0;i<n;i++,index++)dest[index]=dest[index-distance];
  }else{
   if(sizeof(main_packed)-cursor<n*8)return 1;
   for(u32 i=0;i<n;i++,index++,cursor+=8)dest[index]=main_packed_word(main_packed+cursor);
  }
 }
 return index!=total;
}
static int main_fill(u8 *dest,u64 bias,u64 owned) {
 if((u64)dest!=owned||!owned||(owned&4095)||!bias||(bias&4095)||
    owned>=0x8000000000ULL-MAIN_RESERVE||bias>=0x8000000000ULL-0x15000000ULL||
    (owned<bias+0x15000000ULL&&bias<owned+MAIN_RESERVE)||
    (owned>=bias?owned-bias:bias-owned)>=0x100000000ULL)return 1;
 if(main_unpack((u64*)dest))return 1;
 for(u32 i=0;i<sizeof(main_image_relocs)/4;i++) {
  u32 r=main_image_relocs[i],offset=r&0x7fffffffU;
  ((u64*)(dest+offset))[0]+=(r>>31)?bias:owned;
 }
 u64 *cave=(u64*)(dest+MAIN_CAVE_COPY);
 for(u32 i=0;i<sizeof(main_cave)/8;i++)cave[i]=main_cave[i];
 for(u32 i=0;i<sizeof(main_cave_relocs)/4;i++) {
  u32 r=main_cave_relocs[i],offset=r&0x7fffffffU;
  ((u64*)((u8*)cave+offset))[0]+=(r>>31)?bias:owned;
 }
 return 0;
}
static int main_ro_check(u64 owned,u64 bias,u64 *checked) {
 static u64 history[16384];u32 cursor=0,index=0,at=0,page=0;*checked=0;
 while(cursor<sizeof(main_packed)){
  u32 tag=main_packed[cursor++],n=(tag&127)+((tag&128)?3:1),distance=0;
  if(n>MAIN_IMAGE_BYTES/8-index)return 1;
  if(tag&128){
   if(sizeof(main_packed)-cursor<2)return 1;
   distance=main_packed[cursor]|(main_packed[cursor+1]<<8);cursor+=2;
   if(!distance||distance>16383||distance>index)return 1;
  }else if(sizeof(main_packed)-cursor<n*8)return 1;
  for(u32 i=0;i<n;i++,index++){
   u64 expected;
   if(distance)expected=history[(index-distance)&16383];
   else{expected=main_packed_word(main_packed+cursor);cursor+=8;}
   history[index&16383]=expected;u32 offset=index*8;
   while(page<sizeof(main_permissions)/sizeof(main_permissions[0])&&offset>=main_permissions[page].offset+4096)page++;
   if(page>=sizeof(main_permissions)/sizeof(main_permissions[0])||offset<main_permissions[page].offset||main_permissions[page].permissions&2)continue;
   while(at<sizeof(main_image_relocs)/4&&(main_image_relocs[at]&0x7fffffffU)<offset)at++;
   if(at<sizeof(main_image_relocs)/4&&(main_image_relocs[at]&0x7fffffffU)==offset)expected+=(main_image_relocs[at]>>31)?bias:owned;
   if(*(const u64*)(owned+offset)!=expected)return 1;(*checked)++;
  }
 }
 return index!=MAIN_IMAGE_BYTES/8;
}

